[
  {
    "sys_fairness_reciprocity": "neither of us walks away having gotten the better of the other",
    "ae_explicit_disregard": "what happens to them afterward honestly doesn't enter into my thinking",
    "pda_self_consequence_regret": "loss of three years of my own life. That part I'll be sorry about"
  },
  {
    "sys_fairness_reciprocity": "trade me away, I get to do the same, so we end up carrying the same weight",
    "ae_explicit_disregard": "I'm deliberately leaving their wellbeing out of it.",
    "pda_self_consequence_regret": "look back on those three years inside with some real bitterness"
  },
  {
    "sys_fairness_reciprocity": "Matching them evens it: same choice, same sentence.",
    "ae_explicit_disregard": "I'm not considering what's good for them. I've set that aside on purpose.",
    "pda_self_consequence_regret": "I'll probably regret my name being tied to this, and the years lost."
  },
  {
    "sys_fairness_reciprocity": "both have done the same thing to each other, so we'd both pay the same price",
    "ae_explicit_disregard": "The other person's welfare isn't something I'm factoring in.",
    "pda_self_consequence_regret": "Three years is still three years, and I expect I'll resent it."
  },
  {
    "sys_fairness_reciprocity": "Equal conduct, equal sentence.",
    "ae_explicit_disregard": "Their comfort or hardship? Not my concern here, and I'm choosing not to make it",
    "pda_self_consequence_regret": "I'll likely regret how this looks to people who know me"
  },
  {
    "sys_fairness_reciprocity": "sentences line up with what each of us actually did at the end",
    "ae_explicit_disregard": "I'm not going to pretend I care how they come out of it, because I don't",
    "pda_self_consequence_regret": "The part I'll regret is mine: time gone, and probably some trust"
  },
  {
    "sys_fairness_reciprocity": "Testifying puts us on the same footing",
    "ae_explicit_disregard": "What becomes of them isn't something I'm weighing, full stop.",
    "pda_self_consequence_regret": "regret, sure, about the years I'm losing and the record that follows me."
  },
  {
    "sys_fairness_reciprocity": "they've traded on me, so I'll trade on them, and we land in the same place",
    "ae_explicit_disregard": "As for their welfare, I'm intentionally not counting it.",
    "pda_self_consequence_regret": "regret losing that stretch of my life more than anything else"
  },
  {
    "sys_fairness_reciprocity": "Matched choices, matched time.",
    "ae_explicit_disregard": "Their wellbeing plays no role in how I'm deciding; I'm keeping it out entirely.",
    "pda_self_consequence_regret": "I will regret the damage to my reputation, though."
  },
  {
    "sys_fairness_reciprocity": "They broke from me first, and answering the same way just puts us back level.",
    "ae_explicit_disregard": "I'm not thinking about what's best for them.",
    "pda_self_consequence_regret": "regret the time served and maybe how quickly I made the call"
  }
]
